/bin/bash -lc "python3 - <<'PY'
import subprocess,json
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001']))
print('ROOT KEYS',list(r))
for k,v in r.items():
 if k"'!='"'context': print(k,json.dumps(v))
c=r['context'];print('CONTEXT KEYS',list(c))
for k,v in c.items():
 if k not in ('history','knowledge'): print(k,json.dumps(v))
print('HISTORY COMPACT')
for h in c.get('history',[]):
 print(json.dumps({k:v for k,v in h.items() if k not in ('validation','candidate_diagnostics','config')},separators=(',',':')))
 print('config',json.dumps(h.get('config')),'metrics', {k:v for k,v in h.get('validation',{}).items() if k not in ('slices',)})
 print('diagnostics',json.dumps(h.get('candidate_diagnostics')))
PY"

